package com.aabhix.camera.domain;
import java.io.*;import java.util.*;import javax.xml.parsers.*;import org.w3c.dom.*;
/** Bounded data-only adapter. Unknown private ISP keys are retained, never executed. */
public final class PortableConfig {
    public final Map<String,String> values=new LinkedHashMap<>();public int total,unmapped;
    public static PortableConfig parse(String xml)throws Exception{
        if(xml==null||xml.length()>2_000_000||xml.matches("(?is).*<!\\s*(DOCTYPE|ENTITY).*"))throw new IllegalArgumentException("Unsafe or oversized XML");
        java.util.regex.Matcher tags=java.util.regex.Pattern.compile("(?s)<[^>]*>").matcher(xml);int depth=0,entries=0;while(tags.find()){String tag=tags.group();if(tag.startsWith("<?")||tag.startsWith("<!"))continue;if(tag.startsWith("</"))depth--;else{if(depth+1>3)throw new IllegalArgumentException("Configuration nesting exceeds map/set layout");if(depth==1&&++entries>6000)throw new IllegalArgumentException("Too many configuration entries");if(!tag.endsWith("/>"))depth++;}if(depth<0)throw new IllegalArgumentException("Invalid XML depth");}
        DocumentBuilderFactory factory=DocumentBuilderFactory.newInstance();factory.setExpandEntityReferences(false);Document document=factory.newDocumentBuilder().parse(new org.xml.sax.InputSource(new StringReader(xml)));String root=document.getDocumentElement().getTagName();if(!root.equals("map")&&!root.equals("aabhix-config"))throw new IllegalArgumentException("Expected Android map or Aabhix configuration");
        PortableConfig config=new PortableConfig();Set<String> keys=new HashSet<>();NodeList nodes=document.getDocumentElement().getChildNodes();for(int i=0;i<nodes.getLength();i++){Node node=nodes.item(i);if(!(node instanceof Element))continue;Element entry=(Element)node;String key=entry.getAttribute("name"),value=entry.hasAttribute("value")?entry.getAttribute("value"):entry.getTextContent();if(++config.total>6000||key.length()>200||value.length()>4096||!keys.add(key))throw new IllegalArgumentException("Invalid/duplicate configuration entry");String mapped=key.startsWith("aabhix.")?key.substring(7):key.equals("pref_qjpg_key")?"jpegQuality":key.equals("pref_camera_iso_key")?"iso":null;
            if(mapped!=null&&allowed(mapped)){validate(mapped,value);if(config.values.containsKey(mapped))throw new IllegalArgumentException("Conflicting mapped keys");config.values.put(mapped,value.trim());}else config.unmapped++;
        }return config;
    }
    private static boolean allowed(String key){return Arrays.asList("iso","exposureNs","wb","evSteps","jpegQuality","grid","stableVideo","stabilization","photoFrame","videoFrame","styleId","styleIntensity","original").contains(key);}
    private static void validate(String key,String value){value=value.trim();if(key.equals("styleId")){if(!value.matches("[A-Za-z0-9_.-]{1,160}"))throw new IllegalArgumentException("Invalid style identifier");return;}if(key.equals("styleIntensity")){try{float amount=Float.parseFloat(value);if(!Float.isFinite(amount)||amount<0||amount>1)throw new NumberFormatException();}catch(NumberFormatException e){throw new IllegalArgumentException("Style intensity must be 0 to 1");}return;}if(key.equals("original")||key.equals("grid")||key.equals("stableVideo")||key.equals("stabilization")){if(!value.equals("true")&&!value.equals("false"))throw new IllegalArgumentException("Expected boolean "+key);return;}if(key.endsWith("Frame")){if(!Arrays.asList("none","cinema239","cinema235","cinema185","white","black").contains(value))throw new IllegalArgumentException("Unknown frame");return;}if(key.equals("iso")&&value.equalsIgnoreCase("auto"))return;long number;try{number=Long.parseLong(value);}catch(NumberFormatException e){throw new IllegalArgumentException("Expected integer "+key);}long min=key.equals("jpegQuality")?70:key.equals("evSteps")?-100:key.equals("exposureNs")?1:0,max=key.equals("jpegQuality")?100:key.equals("wb")?8:key.equals("evSteps")?100:key.equals("exposureNs")?30_000_000_000L:1_000_000;if(number<min||number>max)throw new IllegalArgumentException("Out of range "+key);}
    public String summary(){StringBuilder text=new StringBuilder();for(Map.Entry<String,String> value:values.entrySet())text.append(value.getKey()).append(" = ").append(value.getValue()).append('\n');if(values.size()==1&&values.containsKey("jpegQuality"))text.append("\nThis changes JPEG compression only. Preview colors and video do not change.\n");return text+"\nMapped "+values.size()+" / "+total+" entries. "+unmapped+" private or unknown entries are retained only. GCam HDR/denoise/libpatcher processing is not supplied by this XML.";}
}

